"""Render the final seventeen-section record and executor reading from frozen evidence."""
import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parents[1];R=H/'results';SID=H.name
read=lambda p:json.loads(p.read_text())
a=read(R/'analysis.json');v=read(R/'oracle-all-points.json');ent=read(R/'comparison-entering.json');ind=read(H/'indicators.json');catalog=read(R/'predicate-catalog.json');axes=read(H/'axes.json')['groups'];pre=read(R/'preflight_results.json');snap=read(H/'snapshot.json');scan=read(R/'edge-scan.json');responses=read(R/'axis-responses.json');base=a['baseline'];cur=base['current'];controls=a['families']['entering-controls'];owner=(H/'preparation/owner-study-intake.txt').read_text().strip()
lines=[]
def add(s=''):lines.append(s)
def table(headers,rows):
 add('| '+' | '.join(headers)+' |');add('| '+' | '.join('---' for _ in headers)+' |')
 for row in rows:add('| '+' | '.join(str(x) for x in row)+' |')
 add()
add('# Absolute conductor-current margin study');add()
add('## 1. Study header');add()
add(f'**Study id:** {SID}. **Package:** stellarator_tea. **Date executed:** {read(R/"execution-summary.json")["started_at_utc"][:10]}. **Executor:** `/root/current_study`. **Mode:** execute. **Arms:** arm-native.');add()
add('## 2. Intake');add()
for paragraph in owner.split('\n\n'):add('> '+paragraph.replace('\n','\n> '));add()
add('[AGENT] The prepared sample retains all entering controls and eleven performance scenarios at sixteen anchors, two turn-current repartition controls and one selected-envelope/current independence example. Exact coordinate aliases and provenance are retained in `preparation/proposals.json`. Material intervals derive from source evidence; orientation and retention scenarios are engineering choices under the delegated authority above.');add()
add('## 3. Objective and result');add()
add(f'The objective is `stellarator_09__stellaris__lcoe_calc__lcoe`, in dollars/MWh. Reference LCOE is {base["lcoe"]:.8f}. The current calculation adds a screen without changing entering costs. Its reference critical current is {cur["critical_current_reference"]:.8f} A, operating fraction {cur["operating_fraction_reference"]:.9f}, and allowable-fraction margin {cur["margin_fraction"]:.9f}. The allowable current is {cur["allowable_current"]:.8f} A; current margin is {cur["margin_current"]:.8f} A. Reference fit margin remains {base["fit_margin_m"]:.6f} m. Evidence: `results/analysis.json`, `results/comparison-entering.json`.');add()
add(f'All {controls["unique_cases"]} unique entering coordinates fail the current screen under default perpendicular/ideal assembly assumptions. {controls["feasible_19"]} pass the entering nineteen-predicate screen, and {controls["feasible_20"]} pass all twenty. Across the complete sensitivity sample, {a["overall"]["feasible_20"]} conditional cases pass all twenty. Performance-only changes leave all entering numeric outputs and nineteen predicates unchanged. Evidence: `results/analysis.json`, `results/performance-isolation.json`.');add()
table(['Performance scenario','Anchor cases','Current passes','All twenty pass','Reference-fraction range across anchors'],[(name,r['unique_cases'],r['current_passes'],r['feasible_20'],str(r['operating_fraction_range'])) for name,r in a['scenarios'].items()])
add('## 4. Constraint outcomes');add()
add('Counts use unique native cases; each row identifies the exact executing predicate. The old nineteen, the added reference-current predicate, and all twenty are separately retained in `results/analysis.json`. Every native outcome is retained in `results/native-cases.json`.');add()
table(['constraint_id','source_local_identity','satisfied','violated','reference'],[(cid,e['source_local_identity'],a['unique_cases']-a['violation_counts'][cid],a['violation_counts'][cid],'violated' if e['source_local_identity'] in base['violated'] else 'satisfied') for cid,e in catalog.items()])
add('## 5. Framing');add()
add('All groups were proposed and judged as sensitivity. The observed results do not change that framing. Reused geometry/inventory coordinates expose dependencies; source-informed material and assumed assembly factors expose consequences. No continuous boundary or optimized machine is claimed.');add()
table(['Axis','Proposed','Judged','Changed'],[(g['axis'],'sensitivity','sensitivity','no') for g in axes])
add('## 6. Per-axis account');add()
for g in axes:
 axis=g['axis'];blocks=responses[axis];points=[p for b in blocks for p in b['points']];edges=[e for e in scan['edges'] if e['axis']==axis]
 add(f'### {axis}');add()
 add('**Feasible structure applies:** not applicable; this axis is sensitivity-framed.');add()
 if points:
  fractions=[p['current']['operating_fraction_reference'] for p in points]
  add(f'**Observed response applies:** yes. {len(blocks)} matched native blocks contain this axis; operating fraction ranges from {min(fractions):.9g} to {max(fractions):.9g} across their points. `results/axis-responses.json` retains each fixed-other-input block, values, objective and violated predicate identities. This range combines blocks and is not a derivative. No continuous boundary is claimed.');add()
 else:add('**Observed response applies:** yes. This coordinate is retained in a coordinated control block; there is no isolated native pair. `results/axis-responses.json` states the empty matched-block set. Endpoint oracle evidence below is a diagnostic, not a native one-axis response or boundary.');add()
 add('From the current conditional anchor, endpoint diagnostics are '+ '; '.join(f'{e["edge"]}={e["value"]}: '+('unsupported field domain; no predicate verdict' if e.get('outcome')=='unsupported_field_domain' else (', '.join(e['violated']) if e['violated'] else 'all predicates satisfied')) for e in edges)+'. See `results/edge-scan.json`; all native violation locations are in `results/native-cases.json`.');add()
add('## 7. Axis groups');add()
table(['Axis','Entry key','Provenance'],[(g['axis'],e['key'],e['provenance']) for g in axes for e in g['keys']])
add('All groups are complete public design-attribute groups in the released contract. No physical-identity tie is introduced. `axes.json` and `indicators.json` retain the declaration and mechanical validation.');add()
add('## 8. Indicators and rulings');add()
table(['Axis','Indicator','Ruling'],[(g['axis'],'no_constraint_response' if g['no_constraint_response'] else 'constraints_reachable','Sensitivity under explicit owner delegation; all selected values retain this framing') for g in ind['groups']])
add('No proposed axis has `no_constraint_response`; no missing-resistance ruling is needed. The broader manufacturing 500–1400 A/mm² values were declined on the already traced material axis; the production central band and separate sample interval serve the bounded question.');add()
add('Indicators cannot establish monotonicity, physical identity across different key names, or intra-module operand dependency. `constraints_reachable` means only a possible path. The word unresisted is an agent judgment and no tool output here claims it.');add()
add('## 9. Preflight results');add()
add('Every native preflight gate passed. `results/preflight_results.json` records each gate, inputs, command/tool provenance and warnings. Identity and baseline gates read `results/package_identity.json` and `results/baseline_result.json`; both were emitted by the stock route. Cleanliness is additionally retained before/after execution.');add()
table(['Gate','Outcome','Detail'],[(g['gate'],g['status'],g['detail']) for g in pre['gates']])
add('## 10. Execution route and why');add()
add('**Route:** study-local direct-API `StudyRunner` with `PreparedListStrategy`. Coordinated historical coordinates and named performance blocks require a prepared list. The exact baseline first exercised the stock strict loader and all preflight gates passed before the list ran. `study.py` and `execution/execute.py` define this route. **Glue ledger: none.** No adapter supplies model arithmetic.');add()
add('## 11. Study definition and window provenance');add()
add(f'The final independent oracle scanned all {a["unique_cases"]} unique selected coordinates, then both endpoints of all eighteen axes from `{scan["anchor_proposal_id"]}`. This anchor is conditional on its declared orientation assumption; all twenty predicates are satisfied there: {scan["anchor_feasible_20"]}. Supported endpoint failures identify caught diagnostic edges; unsupported-field refusals carry no predicate verdict. Neither identifies continuous boundaries. `results/oracle-scan.json`, `results/edge-scan.json` and `reviews/window-selection.md` retain this decision before native execution.');add()
add('The sample is engineered. Source interval values inform four material scenarios but do not make the whole sample a sourced design domain. All old coordinates were scanned again on this package. Their old feasibility did not define a presumed new feasible window.');add()
add('## 12. Cross-fingerprint correlation and what it means');add()
add(f'Single executed fingerprint; no cross-arm correlation is needed. Separate entering attribution compares {ent["matched_cases"]} historical coordinate rows from the captured entering oracle with new native evidence. All {ent["unchanged_scalar_comparisons"]} mapped entering scalar comparisons and {ent["old_predicate_comparisons"]} old predicate comparisons agree. The complete nineteen-entry predicate catalog is exactly equal; the reference-current predicate is the sole addition. This verifies increments under held assumptions, not historical native re-execution. `results/comparison-entering.json` and copied entering contracts retain the comparison.');add()
add('## 13. Verification');add()
add(f'All-point verification passes {v["scalar_comparisons"]} independent-oracle mapped scalar comparisons and {v["predicate_comparisons"]} independently derived predicate comparisons across {v["cases"]} cases. Standard stratified sample verification also passes. Native-store joins pass. Evidence: `results/oracle-all-points.json`, `results/verification_summary.json`, `results/native-store-check.json`.');add()
add('Integration passed its ten implemented gates, but assert_read_set_covered was not run and has no replacement coverage. This inherited omission remains explicit in preparation/integration-return.json; the study does not repair or claim that assurance. The oracle is a separate implementation of the same stated assumptions; agreement does not establish measured cable performance. Unmapped native channels are explicitly listed in the all-point result and are not claimed independently verified. Paired cost/fit isolation is numerical invariance, not independent validation of unchanged costs. Source qualification, weak-location performance and full coil angle fields are outside this verification.');add()
add('## 14. Review outcomes');add()
table(['Lens','Verdict','Disposition'],[['Original-source/math/interface','Independent conditional PASS','Reused copied source-design review; source assumptions preserved in protocol and preparation.'],['Integrated candidate','Independent audit and native CANDIDATE','Coordinator release and copied candidate evidence authorize execution.'],['Study framing/window','Coordinator check','Copied reviews/preexecution-check.md and window-selection.md.'],['Final study assurance','Pending external review at executor freeze','Executor does not self-certify independence; coordinator will join external review separately.']])
add('## 15. Findings');add()
findings=[('Default absolute current fails','Reference and every entering coordinate fail the default reference-current screen; nominal fit failure persists.','Carry into goal answer'),('Previous feasibility changes','Twelve entering nineteen-predicate passes lose combined feasibility under default current assumptions.','Carry into goal answer'),('Orientation and retention scenarios','Scalar orientation scenarios can admit conditional cases; compounded retention can remove them. They do not establish actual coil angles.','Preserve scenario conditions'),('Material evidence transfer','Statistically inferred normalization and specimen range do not qualify the exact adopted 6 mm × 56 μm product or weakest tape location.','Retain qualification gap'),('Field extrapolation','The fixed high-field domain includes explicit extrapolation beyond approximately 24 T at 20 K.','Retain extrapolation condition'),('Assembly qualification','Ideal sharing and separate retention factors do not model manufacturing, joints, stress history or local thermal/field distributions.','Retain engineering gap'),('Predicate independence','The reference and m000 orientation counterexample show neither selected-envelope nor current-margin predicate implies the other.','Retain both predicates'),('Performance and cost','Performance multipliers change capacity without changing tape inventory, cost or fit; no price for improved material or alignment is modeled.','Retain costing limitation'),('Domain-limited endpoint','Combining the major-radius low endpoint with the conditional anchor gives 32.09058362175721 T, outside the 20–32 T domain. No predicate verdict or physical boundary is inferred.','Retain diagnostic refusal; candidate sample unchanged')]
home='work/orchestration/goals/absolute-conductor-current-margin/goal.md'
table(['Id','Kind','Finding','Disposition','Home'],[(f'`{SID}#{i}`','model',title+': '+finding,disposition,home) for i,(title,finding,disposition) in enumerate(findings,1)])
add('## 16. Snapshot');add()
add('**File:** `snapshot.json`. **sha256:** `'+hashlib.sha256((H/'snapshot.json').read_bytes()).hexdigest()+'`. **Schema version:** 1.');add()
add('## 17. What this record does not contain');add()
add('No native re-execution of the entering package, supplier qualification, full generated implementation/runtime distribution or complete source PDFs is included. Quantitative figure witnesses, source extraction, reviewed interpretation and original PDF identity are retained. Independent final assurance occurs after this executor freeze and is not silently backfilled into these results.');add()
add('**END OF RECORD**')
(H/'record.md').write_text('\n'.join(lines)+'\n')
(H/'synthesis.md').write_text('# Executor synthesis\n\nAuthorship: study executor `/root/current_study`; this is not an independent reading. Snapshot SHA-256: `'+hashlib.sha256((H/'snapshot.json').read_bytes()).hexdigest()+'`.\n\nThe reference critical-current estimate is '+f'{cur["critical_current_reference"]:.2f} A against 50000 A operating current. Its operating fraction is {cur["operating_fraction_reference"]:.6f}, exceeding the declared 0.8 allowance; margin is {cur["margin_current"]:.2f} A. All default entering coordinates fail the new current predicate. The old twelve passes therefore disappear under default performance. Nominal fit still fails by {-base["fit_margin_m"]*1000:.0f} mm. See `results/analysis.json`.\n\nAssumed orientation enhancements permit conditional passes; material variation and compounded retention change their capacity without changing inventory or cost. Both current and selected-envelope predicates remain necessary, as the retained counterexamples show. Every axis remains sensitivity-framed; no boundary or optimized design is inferred.\n\nAll-point oracle comparison and native-store joins pass; the detailed counts and explicit unmapped channels are in `results/oracle-all-points.json`. All nine findings in record §15 remain assigned to the goal for disposition.\n\n## What the record does not support\n\nIt does not qualify a cable, infer a physical orientation from a multiplier, certify the weakest coil segment, or validate extrapolated 20 K performance above approximately 24 T. The inferred source normalization, exact-product transfer and ideal assembly assumptions are retained in `preparation/performance-research.md` and `protocol.md`.\n')
print('Rendered record and executor synthesis')
